"""Real Nextflow publishing and resume; generated bytes, no biological tools."""
import csv
import os
from pathlib import Path
import subprocess
import tempfile
import unittest

from test_storage_publish import _fixture, _native_command


class StandardOutputsTests(unittest.TestCase):
    @unittest.skipIf(os.name == 'nt', 'Native fixture requires POSIX')
    def test_native_publication_and_cached_republication(self):
        command = _native_command()
        if not command:
            self.skipTest('Nextflow runtime not configured')
        with tempfile.TemporaryDirectory(prefix='katana-standard-') as directory:
            root = Path(directory) / 'test'
            _fixture(root, 'retain', full_config=True)
            base = [*command, 'run', 'main.nf', '--mode', 'complete', '-ansi-log', 'false', '-work-dir', 'work']
            for label, extra in [('first', []), ('resume', ['-resume'])]:
                trace = root / (label + '.tsv')
                result = subprocess.run([*base, '-with-trace', str(trace), *extra], cwd=root,
                                        capture_output=True, text=True, timeout=240)
                self.assertEqual(result.returncode, 0, result.stdout[-5000:] + result.stderr[-3000:])
                rows = list(csv.DictReader(trace.open(), delimiter='\t'))
                self.assertTrue(rows)
                self.assertTrue(all(r['status'] == ('COMPLETED' if label == 'first' else 'CACHED') for r in rows))
            output = root / 'results'
            for member in ('rnaseq/qc/fastqc/S1_fastqc.zip', 'rnaseq/salmon/S1/quant.sf',
                           'rnaseq/bam/S1.coordinate.bam', 'rnaseq/star/S1.Log.final.out',
                           'differential/deg/gene.counts.tsv', 'differential/dexseq_exon/DEXSeqResults.B_vs_A.csv',
                           'rnasplicing/rmats/pair/rmats_post/SE.MATS.JCEC.txt'):
                self.assertTrue((output / member).is_file(), member)
            self.assertFalse((output / 'katana_bundle').exists())
            self.assertFalse((output / 'reference_index').exists())
            self.assertTrue((output / 'pipeline_info/reference/reference.sha256').is_file())
            self.assertFalse((output / 'pipeline_info/reference/genome.fasta').exists())
            self.assertFalse(any(output.rglob('*.fq.gz')))
            self.assertFalse(any(path.is_symlink() for path in output.rglob('*')))


if __name__ == '__main__':
    unittest.main()
